#!/usr/bin/env python3
# PATH: fix.py
# GOLDEN SEED -- fix121: Settings page redesigned on the Reports/Report
# Studio baseline, as requested.
#
#   1. TAB DOCK REPLACES THE FIVE STACKED PANELS. Appearance, Security,
#      Staff Governance, Danger Zone and the deleted-plots archive used
#      to be five independently-collapsing hwPanels, always all visible,
#      stacked top to bottom. They are now five tabs in a chip dock --
#      the exact spec Report Studio uses for its dataset row (Projects /
#      Clients / Payments / Expenses / Company): a pill per section,
#      label + a Space Mono count on the right, solid-fill orange when
#      selected. One section is on screen at a time, in a single card.
#   2. ONE CARD, RECOLORED PER SECTION INSTEAD OF FIVE FIXED COLORS.
#      The old hwPanel[data-kind] rules hard-wired one accent per panel.
#      The new workstationCard exposes a single --accent custom property
#      that Appearance/Security/Staff/Danger/Archive each set to their
#      own hue (orange/cyan/violet/red/slate) -- the head title, the
#      focus ring, the hover-glow border and even the commit button all
#      key off that one variable, so recoloring a section is a single
#      declaration instead of five duplicated rule blocks.
#   3. CARD CHROME LIFTED FROM REPORT STUDIO, NOT REINVENTED. Same
#      gradient body (#3a5a5c -> #2a4a4c -> #213E40), same border-warms-
#      to-accent + shadow-deepens hover, same #162a2c panelHeadRow with
#      a Cinzel-serif uppercase title and a plain rotating chevron glyph
#      (no boxed button), same CornerDecor corner brackets + pins as
#      every other collapsible card in the app (Reports, Intake,
#      Clients, the digital folder).
#   4. BUTTON LANGUAGE UNIFIED. commitBtn/wipeBtn drop the translateY
#      lift they used to share with nothing else in the app and switch
#      to Report Studio's .useBtn spec: solid fill, recolor-only hover,
#      shadow bloom, no motion. addOpBtn keeps its ghost-button shape
#      but now recolors to violet (Staff's accent) instead of orange,
#      so it visually belongs to the tab it lives on.
#   5. DANGER ZONE gets its own red-tinted alert strip (.dangerAlert),
#      matching the shape Security's alert already used, instead of
#      dropping straight into the wipe field with no framing sentence.
#
# Whole-file replacement patches (base64-embedded, decoded at run time)
# against known-good source text, not a line-level diff -- the redesign
# touches nearly every rule in both files, so a find/replace against the
# ENTIRE previous file is more honest than a wall of tiny fragments that
# would be just as likely to drift out of sync with each other. Runs
# `npm run build` before committing if node_modules is installed and
# refuses to commit on a red build, same gate fix76 added.
import base64
import os
import subprocess
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))
FRONTEND = os.path.join(ROOT, "erp-frontend")
SRC = os.path.join(FRONTEND, "src")

SETTINGS_JSX = os.path.join(SRC, "pages", "settings", "SettingsPage.jsx")
SETTINGS_CSS = os.path.join(SRC, "pages", "settings", "SettingsPage.module.css")


def apply_patches(path, patches):
    with open(path, "r", encoding="utf-8") as f:
        text = f.read()

    rel = os.path.relpath(path, ROOT)
    applied = 0
    for old, new, desc in patches:
        if old not in text:
            if new and new in text:
                print("skip: " + rel + " -- '" + desc + "' already applied")
            else:
                print("WARN: " + rel + " -- '" + desc + "' did not match expected text, check manually")
            continue
        text = text.replace(old, new, 1)
        applied += 1

    if applied:
        with open(path, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
        print("written: " + rel + " (" + str(applied) + "/" + str(len(patches)) + " patch(es) applied)")
    else:
        print("skip: " + rel + " -- no patches applied")
    return applied


def d(b64_str):
    return base64.b64decode(b64_str).decode("utf-8")


